export type ChatActionMenuAction = 'copy' | 'replay' | 'delete'

export interface ChatActionMenuItem {
  action: ChatActionMenuAction
  label: string
  icon: string
  danger?: boolean
}

export function createChatActionMenuItems(options: {
  canCopy: boolean
  canReplay: boolean
  canDelete: boolean
  labels: Record<ChatActionMenuAction, string>
}): ChatActionMenuItem[] {
  return [
    options.canCopy
      ? {
          action: 'copy',
          label: options.labels.copy,
          icon: 'i-solar:copy-bold',
        }
      : null,
    options.canReplay
      ? {
          action: 'replay',
          label: options.labels.replay,
          icon: 'i-solar:restart-bold',
        }
      : null,
    options.canDelete
      ? {
          action: 'delete',
          label: options.labels.delete,
          icon: 'i-solar:trash-bin-minimalistic-bold',
          danger: true,
        }
      : null,
  ].filter(Boolean) as ChatActionMenuItem[]
}
