<script setup lang="ts">
import type { ChatAssistantMessage, ChatHistoryItem, ChatSlices, ChatSlicesText } from '../../../../types/chat'

import { computed } from 'vue'
import { useI18n } from 'vue-i18n'

import ChatResponsePart from './response-part.vue'
import ChatToolCallBlock from './tool-call-block.vue'

import { useChatSpeechReplayStore } from '../../../../stores/chat/speech-replay-store'
import { MarkdownRenderer } from '../../../markdown'
import { getAssistantVisibleText, getChatHistoryItemCopyText } from '../utils'
import { ChatActionMenu } from './action-menu'

const props = withDefaults(defineProps<{
  isStreaming?: boolean
  message: ChatAssistantMessage & { id?: string }
  label: string
  showPlaceholder?: boolean
  variant?: 'desktop' | 'mobile'
}>(), {
  isStreaming: false,
  showPlaceholder: false,
  variant: 'desktop',
})

const emit = defineEmits<{
  (e: 'copy'): void
  (e: 'replay'): void
  (e: 'delete'): void
}>()

const { t } = useI18n()
const speechReplayStore = useChatSpeechReplayStore()
const visibleText = computed(() => getAssistantVisibleText(props.message, {
  preferDisplayText: !props.isStreaming,
}))
const resolvedSlices = computed<ChatSlices[]>(() => {
  const nonTextSlices = props.message.slices?.filter(slice => slice.type !== 'text') ?? []

  if (visibleText.value.trim()) {
    return [
      { type: 'text', text: visibleText.value } satisfies ChatSlicesText,
      ...nonTextSlices,
    ]
  }

  return nonTextSlices
})

const showLoader = computed(() => props.showPlaceholder && resolvedSlices.value.length === 0)
const containerClass = computed(() => props.variant === 'mobile' ? 'mr-0' : 'mr-12')
const boxClasses = computed(() => [
  props.variant === 'mobile' ? 'px-2 py-2 text-sm bg-primary-50/90 dark:bg-primary-950/90' : 'px-3 py-3 bg-primary-50/80 dark:bg-primary-950/80',
])
const copyText = computed(() => getChatHistoryItemCopyText(props.message as ChatHistoryItem))
const canReplay = computed(() => {
  void speechReplayStore.replayVersion
  return speechReplayStore.hasReplay(props.message.id)
})
const showSpeechDebug = computed(() => import.meta.env.DEV && (
  !!props.message.displayText?.trim()
  || !!props.message.speechText?.trim()
  || props.message.speechDebug?.provider === 'frieren-dual-speech'
))

async function replaySpeech() {
  await speechReplayStore.replayMessage(props.message.id)
  emit('replay')
}
</script>

<template>
  <div flex :class="containerClass" class="ph-no-capture">
    <ChatActionMenu
      :copy-text="copyText"
      :can-replay="canReplay"
      :can-delete="!showPlaceholder"
      @copy="emit('copy')"
      @replay="void replaySpeech()"
      @delete="emit('delete')"
    >
      <template #default="{ setMeasuredElement }">
        <div
          :ref="setMeasuredElement"
          flex="~ col" shadow="sm primary-200/50 dark:none"
          min-w-20 rounded-xl h="unset <sm:fit"
          :class="boxClasses"
        >
          <div>
            <span text-sm text="black/60 dark:white/65" font-normal class="inline <sm:hidden">{{ label }}</span>
          </div>
          <div v-if="resolvedSlices.length > 0" class="break-words" text="primary-700 dark:primary-100">
            <template v-for="(slice, sliceIndex) in resolvedSlices" :key="sliceIndex">
              <ChatToolCallBlock
                v-if="slice.type === 'tool-call'"
                :tool-name="slice.toolCall.toolName"
                :args="slice.toolCall.args"
                class="mb-2"
              />
              <template v-else-if="slice.type === 'tool-call-result'" />
              <template v-else-if="slice.type === 'text'">
                <div v-if="isStreaming" class="whitespace-pre-wrap">
                  {{ slice.text }}
                </div>
                <MarkdownRenderer v-else :content="slice.text" />
              </template>
            </template>
          </div>
          <div v-else-if="showLoader" i-eos-icons:three-dots-loading />

          <details
            v-if="showSpeechDebug"
            :class="[
              'mt-3 rounded-lg border border-primary-200/70 px-3 py-2 text-xs',
              'bg-white/65 text-primary-900 dark:border-primary-700/70 dark:bg-black/20 dark:text-primary-100',
            ]"
          >
            <summary class="cursor-pointer select-none font-medium opacity-80">
              {{ t('stage.chat.speech-debug.title') }}
            </summary>
            <div class="grid mt-2 gap-2">
              <div v-if="message.displayText" class="grid gap-1">
                <span class="font-medium opacity-70">{{ t('stage.chat.speech-debug.display-text') }}</span>
                <code class="break-words rounded bg-black/5 px-2 py-1 dark:bg-white/10">{{ message.displayText }}</code>
              </div>
              <div v-if="message.speechText" class="grid gap-1">
                <span class="font-medium opacity-70">{{ t('stage.chat.speech-debug.speech-text') }}</span>
                <code class="break-words rounded bg-black/5 px-2 py-1 dark:bg-white/10">{{ message.speechText }}</code>
              </div>
            </div>
          </details>

          <ChatResponsePart
            v-if="message.categorization"
            :message="message"
            :variant="variant"
          />
        </div>
      </template>
    </ChatActionMenu>
  </div>
</template>
